nextflow_process {

    name "Test Process CENTRIFUGER_QUANTIFICATION"
    script "../main.nf"
    process "CENTRIFUGER_QUANTIFICATION"

    tag "modules"
    tag "modules_nfcore"
    tag "centrifuger"
    tag "centrifuger/quantification"
    tag "centrifuger/centrifuger"

    test("sarscov2 - fastq_se") {
        def db
        setup {
            db = extract('https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/delete_me/cfr_files_short.tar.gz')
            run("CENTRIFUGER_CENTRIFUGER") {

            script "../../../centrifuger/centrifuger/main.nf"
                process {
                    """
                    input[0] = [
                            [id: 'test', single_end: true],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                        ]
                    input[1] = [ [id:'sarscov2'], file('${db}') ]
                    input[2] = true
                    input[3] = true
                    input[4] = []
                    input[5] = []
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = CENTRIFUGER_CENTRIFUGER.out.classification_file.map { meta, file -> [[id: 'quant'], file] }
                input[1] = [ [id:'sarscov2'], file('${db}') ]
                input[2] = []
                input[3] = []
                input[4] = []
                """
            }
        }
        then {
            assert process.success
            assertAll(
                { assert process.success },
                { assert snapshot(
                file(process.out.report_file[0][1]).name,
                process.out.findAll { key, val -> key.startsWith('versions') }
                ).match()
                }

            )
        }

    }
    test("sarscov2 - quantification - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [id: 'quant'], [] ]
                input[1] = [ [id:'sarscov2'], [] ]
                input[2] = []
                input[3] = []
                input[4] = []
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}
